CREATE TABLE order_manual_tender_settlements(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id) ON DELETE RESTRICT,organization_id uuid NOT NULL,branch_id uuid NOT NULL,terminal_id uuid NOT NULL,idempotency_key uuid NOT NULL,method text NOT NULL CHECK(method IN('cash','promptpay_manual')),amount numeric(19,4) NOT NULL CHECK(amount>0),currency char(3) NOT NULL CHECK(btrim(currency)='THB'),operator_subject_id text NOT NULL CHECK(char_length(btrim(operator_subject_id)) BETWEEN 1 AND 200),authorization_decision_id uuid NOT NULL,receipt_confirmed boolean NOT NULL,bank_reference text NULL CHECK(bank_reference IS NULL OR char_length(btrim(bank_reference)) BETWEEN 1 AND 64),request_fingerprint char(64) NOT NULL CHECK(request_fingerprint ~ '^[0-9a-f]{64}$'),occurred_at_utc timestamptz NOT NULL,CONSTRAINT uq_order_manual_tender_idempotency UNIQUE(organization_id,branch_id,idempotency_key),CONSTRAINT ck_order_manual_tender_evidence CHECK((method='promptpay_manual' AND receipt_confirmed) OR (method='cash' AND bank_reference IS NULL)));
CREATE INDEX ix_order_manual_tender_branch_time ON order_manual_tender_settlements(organization_id,branch_id,occurred_at_utc,id);
CREATE FUNCTION reject_order_manual_tender_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'order_manual_tender_settlements is append-only'; END $$;
CREATE TRIGGER trg_order_manual_tender_append_only BEFORE UPDATE OR DELETE ON order_manual_tender_settlements FOR EACH ROW EXECUTE FUNCTION reject_order_manual_tender_mutation();
